package com.mortimercalculator;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("MortimerCalculator")
public interface MortimerCalculatorConfig extends Config
{
	enum PriorityComparedToHeart {
		NO_VALUE,
		EQUAL_VALUE,
		HIGHER_PRIORITY
	}

	@ConfigSection(name = "Settings", description = "General use settings", position = -100)
	String settingsSection = "Settings";
	@ConfigItem(
		position = 0,
		section = settingsSection,
		keyName = "eliteCas",
		name = "Elite CAs",
		description = "Enable if Elite or higher Combat Achievement rewards have been claimed"
	)
	default boolean eliteCas()
	{
		return true;
	}
	@ConfigItem(
			position = 1,
			section = settingsSection,
			keyName = "hideWhenAway",
			name = "Hide when away",
			description = "Hide side panel when task window is closed"
	)
	default boolean hideWhenAway()
	{
		return true;
	}
	@ConfigItem(
			position = 2,
			section = settingsSection,
			keyName = "wildernessPresets",
			name = "Wilderness presets",
			description = "Enable if doing tasks in the Wilderness when possible for the boosted superior rate and cannon compatibility.<br>" +
					"Overrides KPH, travel time, and wilderness advanced settings for Jellies, Nechryael, Abyssal Demons, and Dust Devils, as well as the \"Time to heart\" setting.<br>" +
					"To use custom values for these, leave this  setting disabled and tweak the affected settings as desired."
	)
	default boolean wildernessPresets()
	{
		return false;
	}

	@ConfigSection(name = "Settings (Advanced)", description = "Change values used for calculations", position = -10, closedByDefault = true)
	String advancedSettingsSection = "Settings (Advanced)";
	@ConfigItem(
			position = 0,
			section = advancedSettingsSection,
			keyName = "prepTime",
			name = "Ticks until geared",
			description = "Total ticks between finishing the previous task and being geared for the new one, does NOT include travel time to task location"
	)
	default int prepTime()
	{
		return 30;
	}
	@ConfigItem(
			position = 1,
			section = advancedSettingsSection,
			keyName = "timeToHeart",
			name = "Time to heart",
			description = "Estimated ticks to obtain an Imbued Heart"
	)
	default int timeToHeart()
	{
		return 393051;
	}
	@ConfigItem(
			position = 2,
			section = advancedSettingsSection,
			keyName = "showTimeWasted",
			name = "Show time wasted per task",
			description = "Show time wasted per task, the metric used for choosing which is the best (lower is better)"
	)
	default boolean showTimeWasted()
	{
		return false;
	}
	@ConfigItem(
			position = 3,
			section = advancedSettingsSection,
			keyName = "skipSuggestions",
			name = "Skips",
			description = "Suggest skipping when the best option is exceptionally slow"
	)
	default boolean skipSuggestions() { return true; }
	@ConfigItem(
			position = 4,
			section = advancedSettingsSection,
			keyName = "pointsPerHour",
			name = "Points per hour",
			description = "Estimated points you can obtain per hour through Turael skipping (used for determining when skipping is worth it)"
	)
	default int pointsPerHour()
	{
		return 300;
	}
	@ConfigItem(
			position = 5,
			section = advancedSettingsSection,
			keyName = "blockSuggestions",
			name = "Blocks",
			description = "Suggest blocking when no good option is available, but one of the worst tasks is"
	)
	default boolean blockSuggestions() { return true; }

